// intake.ps1 prints one JSON object. A null batch means the drop folder was
// empty, which is the normal state of a watched folder rather than a fault.
const raw = ($input.first().json.stdout || '').trim();

let claim;
try {
  claim = JSON.parse(raw.split(/\r?\n/).pop());
} catch (e) {
  throw new Error(`intake.ps1 did not return JSON: ${raw.slice(0, 300)}`);
}

return [{ json: claim }];

// One JSON line per image. Count them rather than trusting the exit code:
// a batch where 2 of 40 files were corrupt is a partial success worth keeping,
// not something to throw away wholesale.
const claim = $('Read claim').first().json;
const stdout = $input.first().json.stdout || '';
const stderr = $input.first().json.stderr || '';

const ok = [];
const bad = [];

for (const line of stdout.split(/\r?\n/)) {
  const t = line.trim();
  if (!t) continue;
  let row;
  try { row = JSON.parse(t); } catch { continue; }
  (row.error ? bad : ok).push(row);
}

// Nothing parsed at all means the processor never really ran — a missing
// node, a bad path, sharp not installed. That is a batch failure.
const hardFailure = ok.length === 0;

return [{
  json: {
    batch: claim.batch,
    outPath: claim.outPath,
    claimed: claim.count,
    processed: ok.length,
    failed: bad.length,
    hardFailure,
    // How many shots had a backdrop clean enough to key. A sudden drop here
    // usually means the shoot moved to a different surface.
    keyed: ok.filter((r) => r.keyedBackground).length,
    files: ok.flatMap((r) => r.outputs.map((o) => o.name)).slice(0, 40),
    problems: bad.slice(0, 10),
    stderr: hardFailure ? stderr.slice(0, 600) : undefined,
  },
}];

// What the run actually did. Wire a Slack/email node after this if you want
// to be told; most runs are idle and not worth a message.
const r = $('Read results').first().json;

return [{
  json: {
    batch: r.batch,
    result: r.hardFailure ? 'FAILED' : (r.failed ? 'partial' : 'ok'),
    claimed: r.claimed,
    processed: r.processed,
    failed: r.failed,
    backdropKeyed: `${r.keyed}/${r.processed}`,
    output: r.outPath,
    problems: r.problems,
  },
}];
